package main

// Hand-rolled "codegen" for the spike: builds the generated Go files the way
// PLAN.md §3.1–3.3 describes (inline /*line*/ directive before every copied
// user span, reset directive after it naming the generated file and the true
// position of the next character). It tracks its own output line/col.

import (
	"fmt"
	"strings"
)

type genFile struct {
	base  string // "decl.go" / "render.go"
	orbit string // .orbit path relative to the generated file's directory
	b     strings.Builder
	line  int // 1-based line of the next byte
	col   int // 1-based byte column of the next byte
}

func newGen(base, orbit string) *genFile {
	return &genFile{base: base, orbit: orbit, line: 1, col: 1}
}

func (g *genFile) raw(s string) *genFile {
	g.b.WriteString(s)
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			g.line++
			g.col = 1
		} else {
			g.col++
		}
	}
	return g
}

// span copies user text s that starts at orbit line:col, framed by directives.
func (g *genFile) span(line, col int, s string) *genFile {
	g.raw(fmt.Sprintf("/*line %s:%d:%d*/", g.orbit, line, col))
	g.raw(s)
	// Reset: the comment's own length shifts the column it must name.
	c := g.col
	for {
		d := fmt.Sprintf("/*line %s:%d:%d*/", g.base, g.line, c)
		if g.col+len(d) == c {
			g.raw(d)
			break
		}
		c = g.col + len(d)
	}
	return g
}

func (g *genFile) String() string { return g.b.String() }

const header = "// Code generated by orbit. DO NOT EDIT.\n\n"

const cardOrbit = "../../../../src/components/Card.orbit"
const pageOrbit = "../../../../src/pages/index.orbit"

// cardProps is the Props span copied from Card.orbit:3:1.
const cardProps = "type Props struct {\n    Post     posts.Post\n    Featured bool\n}"
const cardPropsTags = "type Props struct {\n    Post     posts.Post\n    Featured bool\n    Tags     []string\n}"

func renderHook(pkgPath string) string {
	return `var Orbit__Render func(*orbit.Ctx, *orbit.Writer, Props, orbit.Slots) error

func Render(ctx *orbit.Ctx, w *orbit.Writer, props Props, slots orbit.Slots) error {
	if Orbit__Render == nil {
		panic("orbit: ` + pkgPath + ` not linked; import example.com/blog/orbit_gen/app")
	}
	return Orbit__Render(ctx, w, props, slots)
}
`
}

func genCardDecl(props string) string { return genCompDecl("Card", "card", props) }

// genCompDecl builds the decl file of a Card-like component src/components/<Name>.orbit.
func genCompDecl(name, pkg, props string) string {
	g := newGen("decl.go", "../../../../src/components/"+name+".orbit")
	g.raw(header + "package " + pkg + "\n\nimport (\n\torbit \"github.com/bertrandkhe/orbit\"\n\t")
	g.span(2, 8, `"example.com/blog/internal/posts"`)
	g.raw("\n)\n\n")
	g.span(3, 1, props)
	g.raw("\n\n" + renderHook("src/components/"+name+".orbit"))
	return g.String()
}

// cardImplOpts lets checks swap individual user spans.
type cardImplOpts struct {
	body  string // Card.orbit:8:1
	title string // Card.orbit:11:18 expression
}

func genCardImpl(o cardImplOpts) string { return genCompImpl("Card", "card", o) }

func genCompImpl(name, pkg string, o cardImplOpts) string {
	if o.body == "" {
		o.body = "url := href(props.Post)"
	}
	if o.title == "" {
		o.title = "props.Post.Title"
	}
	g := newGen("render.go", "../../../../src/components/"+name+".orbit")
	g.raw(header + "package " + pkg + "\n\nimport (\n\torbit \"github.com/bertrandkhe/orbit\"\n\t. \"example.com/blog/orbit_gen/decl/components/" + pkg + "\"\n\t")
	g.span(2, 8, `"example.com/blog/internal/posts"`)
	g.raw("\n)\n\n")
	g.span(7, 1, `func href(p posts.Post) string { return "/blog/" + p.Slug + "/" }`)
	g.raw("\n\nfunc init() { Orbit__Render = orbit__render }\n\n")
	g.raw("func orbit__render(ctx *orbit.Ctx, orbit__w *orbit.Writer, props Props, slots orbit.Slots) error {\n")
	g.raw("\tif orbit__err := orbit__w.Enter(\"src/components/" + name + ".orbit\"); orbit__err != nil {\n\t\treturn orbit__err\n\t}\n")
	g.raw("\tdefer orbit__w.Leave()\n\tlocals := orbit.LocalsOf[orbit.NoLocals](ctx)\n\t_, _, _, _ = ctx, props, slots, locals\n")
	g.span(8, 1, o.body)
	g.raw("\n\t_ = url\n")
	g.raw("\torbit__w.Raw(\"<article class=\\\"card\\\"\")\n\torbit__w.Attr(\"data-featured\",\n")
	g.span(10, 38, "props.Featured")
	g.raw(",\n\t)\n\torbit__w.Raw(\">\\n  <a\")\n\torbit__w.Attr(\"href\",\n")
	g.span(11, 12, "url")
	g.raw(",\n\t)\n\torbit__w.Raw(\">\")\n\torbit__w.Expr(\n")
	g.span(11, 18, o.title)
	g.raw(",\n\t)\n\torbit__w.Raw(\"</a>\\n  \")\n")
	g.raw("\tif orbit__s := slots.Default; orbit__s != nil {\n\t\tif orbit__err := orbit__s(orbit__w); orbit__err != nil {\n\t\t\treturn orbit__err\n\t\t}\n\t}\n")
	g.raw("\torbit__w.Raw(\"\\n</article>\\n\")\n\treturn orbit__w.Err()\n}\n")
	return g.String()
}

func genPageDecl() string {
	g := newGen("decl.go", pageOrbit)
	g.raw(header + "package index\n\nimport (\n\torbit \"github.com/bertrandkhe/orbit\"\n)\n\ntype Props struct{}\n\n")
	g.raw(renderHook("src/pages/index.orbit"))
	return g.String()
}

type pageImplOpts struct {
	titleBody string // index.orbit:6:1
	h1Expr    string // index.orbit:9:5
	postKey   string // index.orbit:11:9 (field key for attr "post")
	postVal   string // index.orbit:11:15
	extraKey  string // optional extra field key line, e.g. `Tags: []string{"a"},` (no directive)
	scratch   string // body of the synthetic completion function
}

func genPageImpl(o pageImplOpts) string {
	if o.titleBody == "" {
		o.titleBody = `title := "Héllo ✓"`
	}
	if o.h1Expr == "" {
		o.h1Expr = "title"
	}
	if o.postKey == "" {
		o.postKey = "Post"
	}
	if o.postVal == "" {
		o.postVal = "p"
	}
	g := newGen("render.go", pageOrbit)
	g.raw(header + "package index\n\nimport (\n\torbit \"github.com/bertrandkhe/orbit\"\n\t. \"example.com/blog/orbit_gen/decl/pages/index\"\n\t")
	g.span(3, 5, `"example.com/blog/internal/posts"`)
	g.raw("\n\t")
	g.span(4, 5, "Card")
	g.raw(" \"example.com/blog/orbit_gen/decl/components/card\"\n)\n\n")
	g.raw("const Prerender = true\n\nfunc init() { Orbit__Render = orbit__render }\n\n")
	g.raw("func orbit__render(ctx *orbit.Ctx, orbit__w *orbit.Writer, props Props, slots orbit.Slots) error {\n")
	g.raw("\tif orbit__err := orbit__w.Enter(\"src/pages/index.orbit\"); orbit__err != nil {\n\t\treturn orbit__err\n\t}\n")
	g.raw("\tdefer orbit__w.Leave()\n\tlocals := orbit.LocalsOf[orbit.NoLocals](ctx)\n\t_, _, _, _ = ctx, props, slots, locals\n")
	g.span(6, 1, o.titleBody)
	g.raw("\n")
	g.span(7, 1, `all := []posts.Post{{Title: "Hello", Slug: "hello"}}`)
	g.raw("\n\t_, _ = title, all\n")
	g.raw("\torbit__w.Raw(\"<h1>\")\n\torbit__w.Expr(\n")
	g.span(9, 5, o.h1Expr)
	g.raw(",\n\t)\n\torbit__w.Raw(\"</h1>\\n\")\n\tfor ")
	g.span(10, 2, "_, p := range all")
	g.raw(" {\n\t\torbit__w.Raw(\"\\n  \")\n\t\tif orbit__err := ")
	g.span(11, 4, "Card.Render")
	g.raw("(ctx, orbit__w, Card.Props{\n\t\t\t")
	g.span(11, 9, o.postKey)
	g.raw(": ")
	g.span(11, 15, o.postVal)
	g.raw(",\n\t\t\t")
	g.span(11, 18, "Featured")
	g.raw(": true,\n")
	if o.extraKey != "" {
		g.raw("\t\t\t" + o.extraKey + "\n")
	}
	g.raw("\t\t}, orbit.Slots{}); orbit__err != nil {\n\t\t\treturn orbit__err\n\t\t}\n\t\torbit__w.Raw(\"\\n\")\n\t}\n")
	g.raw("\treturn orbit__w.Err()\n}\n")
	if o.scratch != "" {
		g.raw("\n// Synthetic completion scratch (LSP only).\nfunc orbit__complete() {\n\t" + o.scratch + "\n}\n")
	}
	return g.String()
}

// spanLines copies a whole-line user span (a hoisted top-level declaration)
// framed by //line directives on their own lines, which go/ast's
// CommentGroup.Text() strips from doc comments.
func (g *genFile) spanLines(line, col int, s string) *genFile {
	if g.col != 1 {
		g.raw("\n")
	}
	g.raw(fmt.Sprintf("//line %s:%d:%d\n", g.orbit, line, col))
	g.raw(s)
	g.raw("\n")
	g.raw(fmt.Sprintf("//line %s:%d:1\n", g.base, g.line+1))
	return g
}

const cardPropsDoc = "// Props are the card's props.\ntype Props struct {\n    Post     posts.Post // the post to show\n    Featured bool\n}"

// genCardDeclMode builds the Card decl with the Props span emitted inline
// (/*line*/, mode "block") or on its own lines (//line, mode "line").
func genCardDeclMode(props, mode string) string {
	g := newGen("decl.go", cardOrbit)
	g.raw(header + "package card\n\nimport (\n\torbit \"github.com/bertrandkhe/orbit\"\n\t")
	g.span(2, 8, `"example.com/blog/internal/posts"`)
	g.raw("\n)\n\n")
	if mode == "line" {
		g.spanLines(3, 1, props)
	} else {
		g.span(3, 1, props)
	}
	g.raw("\n\n" + renderHook("src/components/Card.orbit"))
	return g.String()
}
